import { Column, Entity, PrimaryGeneratedColumn, Unique } from 'typeorm';
import { TagSelection } from './types';

/**
 * Represents a group of related Tags that make up one question on a vetting form.
 * E.g. the "food_type" group holds Produce, Bread, Frozen food and so on.
 */
@Entity('tag_groups')
@Unique('UQ_tag_groups_key', ['key'])
export class TagGroup {
  /**
   * Unique ID of a TagGroup, generated by the database.
   *
   * E.g. 1, 2, 3
   */
  @PrimaryGeneratedColumn({
    type: 'int',
    primaryKeyConstraintName: 'PK_tag_groups_group_id',
  })
  group_id!: number;

  /**
   * A stable, machine-readable name for the group. Unique across groups.
   *
   * E.g. 'food_type', 'intake_process', 'estimated_wait_time'
   */
  @Column({ type: 'varchar', length: 255 })
  key!: string;

  /**
   * The human-readable name of the group, used for display.
   *
   * E.g. 'Food Types', 'Intake process'
   */
  @Column({ type: 'varchar', length: 255 })
  label!: string;

  /**
   * Whether a resource may have one tag (SINGLE) or several tags (MULTI) from this group.
   * This is enforced by the resources service, not by a database constraint.
   */
  @Column({
    type: 'enum',
    enum: TagSelection,
    enumName: 'tag_selection',
    default: TagSelection.MULTI,
  })
  selection!: TagSelection;
}
